import Editframe from 'editframe';
const client = new Editframe({ token: process.env.EDITFRAME_TOKEN });
await client.videos.create({ clips: [] });

import { createApi } from 'unsplash-js';
const unsplash = createApi({ accessKey: process.env.UNSPLASH_ACCESS_KEY });
const result = await unsplash.search.getPhotos({ query: 'mountains', perPage: 5 });

import Mux from '@mux/mux-node';
const { Video } = new Mux(process.env.MUX_TOKEN, process.env.MUX_SECRET);
await Video.Assets.create({ input: 'https://example.com/video.mp4', playback_policy: 'public' });
